function decodeUtf8(b64: string): string {
  // Electron renderer has Buffer; fall back to atob + TextDecoder elsewhere.
  const g: any = globalThis as any;
  if (g.Buffer) return g.Buffer.from(b64, 'base64').toString('utf-8');
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

export interface InstalledScriptPaths {
  layoutEngineAbs: string;
  pdfExportAbs: string;
}

/**
 * Writes layout_engine.py and pdf_export.py into the plugin folder and points
 * the relevant settings at their absolute paths. Desktop only (spawn/Node).
 *
 * Returns the absolute paths, or null on failure.
 */
export async function installPythonScripts(
  plugin: OpenRouterTranslatorPlugin,
  opts: { overwrite?: boolean } = {}
): Promise<InstalledScriptPaths | null> {
  const adapter = plugin.app.vault.adapter;
  if (!(adapter instanceof FileSystemAdapter)) {
    new Notice('Python scripts can only be installed on desktop.');
    return null;
  }

  const pluginDir = plugin.manifest.dir;
  if (!pluginDir) {
    new Notice('Could not resolve the plugin folder.');
    return null;
  }

  const basePath = adapter.getBasePath();
  const targets = [
    { rel: normalizePath(`${pluginDir}/layout_engine.py`), src: LAYOUT_ENGINE_PY_B64 },
    { rel: normalizePath(`${pluginDir}/pdf_export.py`),    src: PDF_EXPORT_PY_B64 },
  ];

  try {
    for (const t of targets) {
      const exists = await adapter.exists(t.rel);
      if (exists && !opts.overwrite) {
        // Still refresh content so updates land; comment out if you prefer to skip.
        await adapter.write(t.rel, decodeUtf8(t.src));
      } else {
        await adapter.write(t.rel, decodeUtf8(t.src));
      }
    }

    const layoutEngineAbs = `${basePath}/${targets[0].rel}`;
    const pdfExportAbs     = `${basePath}/${targets[1].rel}`;

    // Wire settings so the spawn paths are correct without manual entry.
    plugin.settings.ocrScriptPath = layoutEngineAbs;     // used by ExternalLayoutService
    plugin.settings.mergeScriptPath = pdfExportAbs;       // informational; PdfExportService
    plugin.settings.pdfExportScriptPath = pdfExportAbs;   //   resolves its own path too
    await plugin.saveSettings();

    new Notice('Python scripts installed into the plugin folder.');
    return { layoutEngineAbs, pdfExportAbs };
  } catch (err: any) {
    console.error('[PythonScripts] install failed:', err);
    new Notice(`Failed to install Python scripts: ${err?.message ?? err}`);
    return null;
  }
}
